  "created_by" TEXT,
  "deleted_at" TEXT,
  "row_version" INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY ("owner_department_id") REFERENCES "department"("id") ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS "stage_requirement" (
  "stage_id" TEXT,
  "requirement_type" TEXT NOT NULL,
  "doc_type" TEXT,
  "description" TEXT NOT NULL,
  "is_blocking" INTEGER NOT NULL DEFAULT 0,
  "rule_key" TEXT,
  "id" TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "created_by" TEXT,
  "deleted_at" TEXT,
  "row_version" INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY ("stage_id") REFERENCES "stage_definition"("id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "stage_instance" (
  "opportunity_id" TEXT,
  "project_id" TEXT,
  "stage_id" TEXT,
  "status" TEXT NOT NULL,
  "entered_at" TEXT,
  "completed_at" TEXT,
  "completed_by_user_id" TEXT,
  "hold_reason" TEXT,
  "override_reason" TEXT,
  "notes" TEXT,
  "id" TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "created_by" TEXT,
  "deleted_at" TEXT,
  "row_version" INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY ("stage_id") REFERENCES "stage_definition"("id") ON DELETE RESTRICT,
  FOREIGN KEY ("opportunity_id") REFERENCES "opportunity"("id") ON DELETE CASCADE,
  FOREIGN KEY ("project_id") REFERENCES "project"("id") ON DELETE CASCADE,
  FOREIGN KEY ("completed_by_user_id") REFERENCES "user"("id") ON DELETE SET NULL
);

CREATE TABLE IF NOT EXISTS "audit_log" (
  "entity_type" TEXT NOT NULL,
  "entity_id" TEXT NOT NULL,
  "action" TEXT NOT NULL,
  "field_name" TEXT,
  "old_value" TEXT,
  "new_value" TEXT,
  "user_id" TEXT,
  "at" TEXT NOT NULL,
  "reason" TEXT,
  "id" TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(16)))),
  "created_at" TEXT NOT NULL,
  "updated_at" TEXT NOT NULL,
  "created_by" TEXT,
  "deleted_at" TEXT,
  "row_version" INTEGER NOT NULL DEFAULT 0,
  FOREIGN KEY ("user_id") REFERENCES "user"("id") ON DELETE RESTRICT
);

-- Choice lists (configurable dropdown values)
CREATE TABLE IF NOT EXISTS "choice_value" (
  "list_key" TEXT NOT NULL,
  "sort_order" INTEGER NOT NULL DEFAULT 0,
  "value" TEXT NOT NULL,
  PRIMARY KEY ("list_key", "sort_order")
);

